{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_knowledge_status.schema.json",
  "title": "Navia V2 Knowledge Service Status",
  "type": "object",
  "required": ["schemaVersion", "observedAt", "runtimeStatus", "frontendInferredRuntimeStatus", "adapterStatus", "dataServiceStatus", "sourceBuildStatus"],
  "properties": {
    "schemaVersion": { "const": "v2-knowledge-status-draft-2026-07-10" },
    "observedAt": { "type": "string", "format": "date-time" },
    "frontendInferredRuntimeStatus": {
      "description": "When Runtime transport fails, the frontend must infer runtime offline locally because /v1/knowledge/status is unreachable.",
      "type": "string",
      "enum": ["checking", "online", "offline"]
    },
    "runtimeStatus": {
      "description": "Returned by Runtime only when Runtime is reachable; otherwise frontendInferredRuntimeStatus is authoritative.",
      "type": ["string", "null"],
      "enum": ["checking", "online", null]
    },
    "adapterStatus": {
      "type": "string",
      "enum": ["ready", "degraded", "blocked", "unchecked"]
    },
    "dataServiceStatus": {
      "type": "string",
      "enum": ["unchecked", "connected", "degraded", "auth_required", "unreachable", "version_mismatch"]
    },
    "sourceBuildStatus": {
      "type": "string",
      "enum": ["not_saved", "queued", "ingesting", "building", "trace_ready", "degraded", "failed", "forgotten", "unknown"]
    },
    "capabilities": {
      "type": "object",
      "properties": {
        "workspace": { "type": "boolean" },
        "sourceImport": { "type": "boolean" },
        "buildStatus": { "type": "boolean" },
        "query": { "type": "boolean" },
        "graph": { "type": "boolean" },
        "sourceTrace": { "type": "boolean" },
        "forgetVerification": { "type": "boolean" }
      },
      "additionalProperties": false
    },
    "userAction": {
      "type": "string",
      "enum": ["none", "start_runtime", "configure_adapter", "configure_data_service", "reconnect", "upgrade_data_service", "retry_source_build", "open_debug"]
    },
    "message": { "type": "string" },
    "redactionApplied": { "type": "boolean" }
  },
  "allOf": [
    {
      "if": {
        "properties": {"frontendInferredRuntimeStatus": {"const": "offline"}},
        "required": ["frontendInferredRuntimeStatus"]
      },
      "then": {
        "properties": {
          "runtimeStatus": {"type": "null"},
          "adapterStatus": {"const": "unchecked"},
          "dataServiceStatus": {"const": "unchecked"},
          "sourceBuildStatus": {"const": "unknown"}
        }
      }
    },
    {
      "if": {
        "properties": {"frontendInferredRuntimeStatus": {"const": "online"}},
        "required": ["frontendInferredRuntimeStatus"]
      },
      "then": {"properties": {"runtimeStatus": {"const": "online"}}}
    }
  ],
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_acceptance_manifest.schema.json",
  "title": "V2-PX Acceptance Manifest",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "generatedAt",
    "evidenceClass",
    "acceptanceMode",
    "sourceCorpus",
    "scenarios"
  ],
  "properties": {
    "schemaVersion": {
      "const": "v2-external-brain-acceptance-manifest/v5"
    },
    "generatedAt": {
      "type": "string",
      "format": "date-time"
    },
    "evidenceClass": {
      "enum": ["contract_fixture", "production_acceptance"]
    },
    "acceptanceMode": {
      "enum": ["contract_fixture", "real_chrome_dual_container"]
    },
    "sourceCorpus": {
      "type": "array",
      "minItems": 12,
      "items": {
        "$ref": "#/$defs/SourceSample"
      }
    },
    "scenarios": {
      "type": "array",
      "minItems": 12,
      "items": {
        "$ref": "#/$defs/Scenario"
      }
    }
  },
  "allOf": [
    {
      "if": {"properties": {"evidenceClass": {"const": "contract_fixture"}}, "required": ["evidenceClass"]},
      "then": {"properties": {"acceptanceMode": {"const": "contract_fixture"}}}
    },
    {
      "if": {"properties": {"evidenceClass": {"const": "production_acceptance"}}, "required": ["evidenceClass"]},
      "then": {"properties": {"acceptanceMode": {"const": "real_chrome_dual_container"}}}
    }
  ],
  "$defs": {
    "SourceKind": {
      "type": "string",
      "enum": [
        "real_web",
        "explicit_local_document",
        "note_markdown"
      ]
    },
    "RouteIntent": {
      "type": "string",
      "enum": [
        "source_detail",
        "source_library",
        "ask",
        "graph",
        "permissions"
      ]
    },
    "FaultInjection": {
      "type": "string",
      "enum": [
        "none",
        "runtime_offline",
        "adapter_blocked",
        "data_service_unreachable",
        "source_failed",
        "source_degraded"
      ]
    },
    "CoverageTag": {
      "type": "string",
      "enum": [
        "entry_view_source",
        "entry_open_workspace",
        "entry_open_in_workspace",
        "route_direct_open",
        "route_reload",
        "route_back_reopen",
        "invalid_id_recovery",
        "forbidden_id_recovery",
        "cross_container_identity",
        "tab_reuse",
        "runtime_offline",
        "adapter_blocked",
        "data_service_unreachable",
        "source_failed_or_degraded",
        "permission_grant_revoke",
        "forget_four_surface",
        "responsive_sidepanel_420",
        "responsive_sidepanel_360",
        "responsive_workspace_1280",
        "responsive_workspace_768",
        "accessibility_keyboard_dialog_motion"
      ]
    },
    "SourceSample": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceSampleId",
        "sourceKind",
        "dataMode",
        "originLabel",
        "originRef",
        "contentFingerprint",
        "authorizationMode"
      ],
      "properties": {
        "sourceSampleId": {
          "type": "string",
          "minLength": 1
        },
        "sourceKind": {
          "$ref": "#/$defs/SourceKind"
        },
        "dataMode": {
          "const": "real"
        },
        "originLabel": {
          "type": "string",
          "minLength": 1
        },
        "originRef": {
          "type": "string",
          "minLength": 1
        },
        "contentFingerprint": {
          "type": "object",
          "additionalProperties": false,
          "required": ["algorithm", "inputMode", "artifactPath", "value"],
          "properties": {
            "algorithm": {"const": "sha256"},
            "inputMode": {"const": "raw_bytes_v1"},
            "artifactPath": {
              "type": "string",
              "minLength": 1,
              "pattern": "^(?!https?://)(?!file:)(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$)).+"
            },
            "value": {"type": "string", "pattern": "^[a-f0-9]{64}$"}
          }
        },
        "authorizationMode": {
          "type": "string",
          "enum": [
            "current_page_user_save",
            "explicit_permission_root",
            "user_authored"
          ]
        }
      }
    },
    "Scenario": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "scenarioId",
        "sourceSampleIds",
        "entryPoint",
        "routeIntent",
        "executionMode",
        "viewport",
        "coverageTags",
        "faultInjection",
        "expected"
      ],
      "properties": {
        "scenarioId": {
          "type": "string",
          "minLength": 1
        },
        "sourceSampleIds": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "entryPoint": {
          "type": "string",
          "enum": [
            "view_source",
            "open_workspace",
            "open_in_workspace",
            "direct_route",
            "status_recovery",
            "permission",
            "forget"
          ]
        },
        "routeIntent": {
          "$ref": "#/$defs/RouteIntent"
        },
        "executionMode": {
          "type": "string",
          "enum": [
            "contract_fixture",
            "headless_real_chrome",
            "visible_real_chrome"
          ]
        },
        "viewport": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "width",
            "height"
          ],
          "properties": {
            "width": {
              "type": "integer",
              "minimum": 320
            },
            "height": {
              "type": "integer",
              "minimum": 568
            }
          }
        },
        "coverageTags": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/CoverageTag"
          }
        },
        "faultInjection": {
          "$ref": "#/$defs/FaultInjection"
        },
        "expected": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "outcome",
            "openOutcome",
            "routeRecoveryResult",
            "requiresScreenshot",
            "requiresScreenshotMetadata",
            "requiresIdConsistency",
            "requiresNoDuplicateIngest"
          ],
          "properties": {
            "outcome": {
              "type": "string",
              "enum": [
                "pass",
                "recoverable_error",
                "blocked",
                "degraded"
              ]
            },
            "openOutcome": {
              "enum": [
                "focused_existing", "created_new", "direct_open_restored",
                "recovered", "blocked", "not_applicable"
              ]
            },
            "routeRecoveryResult": {
              "enum": [
                "not_applicable", "restored_direct_open", "restored_after_reload",
                "restored_after_back", "recovered_to_library", "blocked_with_recovery_action"
              ]
            },
            "requiresScreenshot": {
              "const": true
            },
            "requiresScreenshotMetadata": {
              "const": true
            },
            "requiresIdConsistency": {
              "type": "boolean"
            },
            "requiresNoDuplicateIngest": {
              "type": "boolean"
            },
            "expectedErrorCode": {
              "type": "string",
              "enum": [
                "WORKSPACE_NOT_FOUND",
                "SOURCE_NOT_FOUND",
                "FORBIDDEN",
                "INVALID_ROUTE",
                "RUNTIME_OFFLINE",
                "OPEN_WORKSPACE_FAILED"
              ]
            }
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "expected": {
                "properties": {"outcome": {"enum": ["recoverable_error", "blocked"]}},
                "required": ["outcome"]
              }
            }
          },
          "then": {
            "properties": {
              "expected": {"required": ["expectedErrorCode"]}
            }
          }
        },
        {
          "if": {
            "properties": {
              "expected": {
                "properties": {"outcome": {"const": "recoverable_error"}},
                "required": ["outcome"]
              }
            }
          },
          "then": {
            "properties": {
              "expected": {
                "properties": {
                  "openOutcome": {"const": "recovered"},
                  "routeRecoveryResult": {"const": "recovered_to_library"}
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "expected": {
                "properties": {"outcome": {"const": "blocked"}},
                "required": ["outcome"]
              }
            }
          },
          "then": {
            "properties": {
              "expected": {
                "properties": {
                  "openOutcome": {"const": "blocked"},
                  "routeRecoveryResult": {"const": "blocked_with_recovery_action"}
                }
              }
            }
          }
        }
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_report.schema.json",
  "title": "V2-PX Acceptance Report",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "generatedAt",
    "evidenceClass",
    "acceptanceMode",
    "claim",
    "passed",
    "humanReview",
    "summary",
    "gateResults",
    "scenarioResults",
    "testCommands",
    "auditArtifacts",
    "fatalIssues",
    "majorIssues",
    "warnings"
  ],
  "properties": {
    "schemaVersion": {
      "const": "v2-external-brain-report/v12"
    },
    "generatedAt": {
      "type": "string",
      "format": "date-time"
    },
    "evidenceClass": {
      "enum": [
        "contract_fixture",
        "production_acceptance"
      ]
    },
    "acceptanceMode": {
      "enum": [
        "contract_fixture",
        "real_chrome_dual_container"
      ]
    },
    "claim": {
      "enum": [
        "V2-PX External Brain Productization passed dual-container real-Chrome acceptance.",
        "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence.",
        "V2-PX External Brain Productization acceptance did not pass."
      ]
    },
    "passed": {
      "type": "boolean"
    },
    "humanReview": {
      "$ref": "#/$defs/HumanReviewRef"
    },
    "summary": {
      "$ref": "#/$defs/Summary"
    },
    "gateResults": {
      "$ref": "#/$defs/GateResults"
    },
    "scenarioResults": {
      "type": "array",
      "minItems": 12,
      "items": {
        "$ref": "#/$defs/ScenarioResult"
      }
    },
    "testCommands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/TestCommand"
      }
    },
    "auditArtifacts": {
      "$ref": "#/$defs/AuditArtifacts"
    },
    "fatalIssues": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "majorIssues": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "warnings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "contract_fixture"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "humanReview": {
            "properties": {
              "evidenceClass": {
                "const": "contract_fixture"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "production_acceptance"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "humanReview": {
            "properties": {
              "evidenceClass": {
                "const": "production_acceptance"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "contract_fixture"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "acceptanceMode": {
            "const": "contract_fixture"
          },
          "claim": {
            "const": "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence."
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "production_acceptance"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "acceptanceMode": {
            "const": "real_chrome_dual_container"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "passed": {
            "const": true
          }
        },
        "required": [
          "passed"
        ]
      },
      "then": {
        "properties": {
          "claim": {
            "enum": [
              "V2-PX External Brain Productization passed dual-container real-Chrome acceptance.",
              "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence."
            ]
          },
          "humanReview": {
            "allOf": [
              {
                "$ref": "#/$defs/HumanReviewRef"
              },
              {
                "properties": {
                  "status": {
                    "const": "passed"
                  }
                }
              }
            ]
          },
          "fatalIssues": {
            "maxItems": 0
          },
          "majorIssues": {
            "maxItems": 0
          },
          "gateResults": {
            "$ref": "#/$defs/PassedGateResults"
          },
          "scenarioResults": {
            "items": {
              "allOf": [
                {
                  "$ref": "#/$defs/ScenarioResult"
                },
                {
                  "properties": {
                    "passed": {
                      "const": true
                    }
                  }
                }
              ]
            }
          },
          "testCommands": {
            "items": {
              "allOf": [
                {
                  "$ref": "#/$defs/TestCommand"
                },
                {
                  "properties": {
                    "passed": {
                      "const": true
                    }
                  }
                }
              ]
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "passed": {
            "const": false
          }
        },
        "required": [
          "passed"
        ]
      },
      "then": {
        "properties": {
          "claim": {
            "const": "V2-PX External Brain Productization acceptance did not pass."
          }
        }
      }
    }
  ],
  "$defs": {
    "RouteIntent": {
      "enum": [
        "source_detail",
        "source_library",
        "ask",
        "graph",
        "permissions"
      ]
    },
    "WorkspaceErrorCode": {
      "enum": [
        "WORKSPACE_NOT_FOUND",
        "SOURCE_NOT_FOUND",
        "FORBIDDEN",
        "INVALID_ROUTE",
        "RUNTIME_OFFLINE",
        "OPEN_WORKSPACE_FAILED",
        "UNSUPPORTED_HOST_STRATEGY"
      ]
    },
    "Summary": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceCorpusTotal",
        "uniqueRealWebSources",
        "uniqueExplicitLocalDocumentSources",
        "uniqueNoteMarkdownSources",
        "scenariosTotal",
        "scenariosPassed",
        "entryPointsCovered",
        "routesCovered",
        "routeDirectOpenReloadPairs",
        "invalidOrForbiddenRecoverySamples",
        "idConsistencySamples",
        "statusFaultsCovered",
        "permissionSamples",
        "forgetSamples",
        "v2RegressionPassed"
      ],
      "properties": {
        "sourceCorpusTotal": {
          "type": "integer",
          "minimum": 12
        },
        "uniqueRealWebSources": {
          "type": "integer",
          "minimum": 6
        },
        "uniqueExplicitLocalDocumentSources": {
          "type": "integer",
          "minimum": 3
        },
        "uniqueNoteMarkdownSources": {
          "type": "integer",
          "minimum": 3
        },
        "scenariosTotal": {
          "type": "integer",
          "minimum": 12
        },
        "scenariosPassed": {
          "type": "integer",
          "minimum": 0
        },
        "entryPointsCovered": {
          "type": "integer",
          "minimum": 3
        },
        "routesCovered": {
          "type": "integer",
          "minimum": 5
        },
        "routeDirectOpenReloadPairs": {
          "type": "integer",
          "minimum": 5
        },
        "invalidOrForbiddenRecoverySamples": {
          "type": "integer",
          "minimum": 2
        },
        "idConsistencySamples": {
          "type": "integer",
          "minimum": 4
        },
        "statusFaultsCovered": {
          "type": "integer",
          "minimum": 4
        },
        "permissionSamples": {
          "type": "integer",
          "minimum": 3
        },
        "forgetSamples": {
          "type": "integer",
          "minimum": 3
        },
        "v2RegressionPassed": {
          "type": "boolean"
        }
      }
    },
    "GateResults": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "G1_entry",
        "G2_route",
        "G3_lifecycle",
        "G4_architecture",
        "G5_status",
        "G6_ux_accessibility",
        "G7_evidence"
      ],
      "properties": {
        "G1_entry": {
          "type": "boolean"
        },
        "G2_route": {
          "type": "boolean"
        },
        "G3_lifecycle": {
          "type": "boolean"
        },
        "G4_architecture": {
          "type": "boolean"
        },
        "G5_status": {
          "type": "boolean"
        },
        "G6_ux_accessibility": {
          "type": "boolean"
        },
        "G7_evidence": {
          "type": "boolean"
        }
      }
    },
    "PassedGateResults": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "G1_entry",
        "G2_route",
        "G3_lifecycle",
        "G4_architecture",
        "G5_status",
        "G6_ux_accessibility",
        "G7_evidence"
      ],
      "properties": {
        "G1_entry": {
          "const": true
        },
        "G2_route": {
          "const": true
        },
        "G3_lifecycle": {
          "const": true
        },
        "G4_architecture": {
          "const": true
        },
        "G5_status": {
          "const": true
        },
        "G6_ux_accessibility": {
          "const": true
        },
        "G7_evidence": {
          "const": true
        }
      }
    },
    "ObservedIds": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sidePanel",
        "background",
        "runtime",
        "workspace"
      ],
      "properties": {
        "sidePanel": {
          "$ref": "#/$defs/ObservedContainerIds"
        },
        "background": {
          "$ref": "#/$defs/ObservedContainerIds"
        },
        "runtime": {
          "$ref": "#/$defs/ObservedContainerIds"
        },
        "workspace": {
          "$ref": "#/$defs/ObservedContainerIds"
        }
      }
    },
    "ObservedContainerIds": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status"
      ],
      "properties": {
        "status": {
          "enum": [
            "observed",
            "not_applicable",
            "unavailable"
          ]
        },
        "workspaceId": {
          "type": "string",
          "minLength": 1
        },
        "sourceId": {
          "type": "string",
          "minLength": 1
        },
        "operationId": {
          "type": "string",
          "minLength": 1
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "observed"
              }
            },
            "required": [
              "status"
            ]
          },
          "then": {
            "required": [
              "workspaceId"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "status": {
                "enum": [
                  "not_applicable",
                  "unavailable"
                ]
              }
            },
            "required": [
              "status"
            ]
          },
          "then": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "workspaceId"
                  ]
                },
                {
                  "required": [
                    "sourceId"
                  ]
                },
                {
                  "required": [
                    "operationId"
                  ]
                }
              ]
            }
          }
        }
      ]
    },
    "StatusObservation": {
