          "const": "architecture"
        },
        "repositoryCommit": {
          "type": "string",
          "pattern": "^[a-f0-9]{40}([a-f0-9]{24})?$"
        },
        "sourceTreeSha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        },
        "scanRoots": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
            "enum": [
              "apps/chrome-extension/entrypoints/sidepanel",
              "apps/chrome-extension/entrypoints/workspace",
              "apps/chrome-extension/src/modules/knowledge_workspace"
            ]
          },
          "allOf": [
            {
              "contains": {
                "const": "apps/chrome-extension/entrypoints/sidepanel"
              }
            },
            {
              "contains": {
                "const": "apps/chrome-extension/entrypoints/workspace"
              }
            },
            {
              "contains": {
                "const": "apps/chrome-extension/src/modules/knowledge_workspace"
              }
            }
          ]
        },
        "scannedPathIndexSha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        },
        "rulesetId": {
          "const": "v2-px-architecture-boundary/v2"
        },
        "rulesetSha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        },
        "allowlistSha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        },
        "scanManifestArtifact": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "excludedPaths": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "scannedFiles": {
          "type": "integer",
          "minimum": 1
        },
        "violations": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "AxeResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "resultType",
        "serious",
        "critical"
      ],
      "properties": {
        "resultType": {
          "const": "axe"
        },
        "serious": {
          "type": "integer",
          "minimum": 0
        },
        "critical": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "KeyboardResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "resultType",
        "assertionsTotal",
        "assertionsPassed",
        "focusReturnPassed",
        "escapePassed",
        "reducedMotionPassed"
      ],
      "properties": {
        "resultType": {
          "const": "keyboard"
        },
        "assertionsTotal": {
          "type": "integer",
          "minimum": 1
        },
        "assertionsPassed": {
          "type": "integer",
          "minimum": 0
        },
        "focusReturnPassed": {
          "type": "boolean"
        },
        "escapePassed": {
          "type": "boolean"
        },
        "reducedMotionPassed": {
          "type": "boolean"
        }
      }
    },
    "ViewportResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "resultType",
        "width",
        "height",
        "documentScrollWidth",
        "containerScrollWidth",
        "overflowBlockers",
        "overlapBlockers"
      ],
      "properties": {
        "resultType": {
          "const": "viewport"
        },
        "width": {
          "type": "integer",
          "minimum": 320
        },
        "height": {
          "type": "integer",
          "minimum": 568
        },
        "documentScrollWidth": {
          "type": "integer",
          "minimum": 0
        },
        "containerScrollWidth": {
          "type": "integer",
          "minimum": 0
        },
        "overflowBlockers": {
          "type": "integer",
          "minimum": 0
        },
        "overlapBlockers": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "SuiteResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "resultType",
        "assertionsTotal",
        "assertionsPassed"
      ],
      "properties": {
        "resultType": {
          "const": "suite"
        },
        "assertionsTotal": {
          "type": "integer",
          "minimum": 1
        },
        "assertionsPassed": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "AuditArtifacts": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "acceptanceHtml",
        "prdReview",
        "architectureReview",
        "falseGreenAudit",
        "semanticValidatorLog"
      ],
      "properties": {
        "acceptanceHtml": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "prdReview": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "architectureReview": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "falseGreenAudit": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "semanticValidatorLog": {
          "$ref": "#/$defs/ArtifactRef"
        }
      }
    },
    "ArtifactRef": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "sha256"
      ],
      "properties": {
        "path": {
          "type": "string",
          "minLength": 1
        },
        "sha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        }
      }
    },
    "HumanReviewRef": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "evidenceClass",
        "recordPath",
        "recordSha256"
      ],
      "properties": {
        "status": {
          "enum": [
            "pending",
            "passed",
            "failed"
          ]
        },
        "evidenceClass": {
          "enum": [
            "contract_fixture",
            "production_acceptance"
          ]
        },
        "recordPath": {
          "type": "string",
          "minLength": 1
        },
        "recordSha256": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$"
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_screenshot_metadata.schema.json",
  "title": "V2-PX Screenshot Metadata",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion", "scenarioId", "capturedAt", "evidenceClass", "executionMode", "browser",
    "viewport", "imagePath", "imageSha256", "captureVariantId", "captureMode",
    "captureSurface", "capturePhase", "containerEvidence", "entryPoint",
    "routeIntent", "resolvedPath", "routeRecoveryResult", "openOutcome",
    "observedIds", "statusObservation"
  ],
  "properties": {
    "schemaVersion": {"const": "v2-external-brain-screenshot-metadata/v6"},
    "scenarioId": {"type": "string", "minLength": 1},
    "capturedAt": {"type": "string", "format": "date-time"},
    "evidenceClass": {"enum": ["contract_fixture", "production_acceptance"]},
    "executionMode": {"enum": ["contract_fixture", "headless_real_chrome", "visible_real_chrome"]},
    "browser": {"const": "chrome"},
    "viewport": {
      "type": "object", "additionalProperties": false, "required": ["width", "height", "deviceScaleFactor"],
      "properties": {
        "width": {"type": "integer", "minimum": 320},
        "height": {"type": "integer", "minimum": 568},
        "deviceScaleFactor": {"type": "number", "exclusiveMinimum": 0}
      }
    },
    "imagePath": {"type": "string", "minLength": 1},
    "imageSha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
    "captureVariantId": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{2,63}$"},
    "captureMode": {"enum": ["product_surface", "composite_review_only"]},
    "captureSurface": {"enum": ["host_page", "side_panel", "workspace_page", "route_error", "composite_review"]},
    "capturePhase": {"enum": ["entry", "route_ready", "before_action", "after_action", "error_recovery", "after_forget"]},
    "containerEvidence": {
      "type": "object", "additionalProperties": false,
      "required": ["hostPageVisible", "sidePanelVisible", "workspaceVisible"],
      "properties": {
        "hostPageVisible": {"type": "boolean"},
        "sidePanelVisible": {"type": "boolean"},
        "workspaceVisible": {"type": "boolean"}
      }
    },
    "entryPoint": {"enum": ["view_source", "open_workspace", "open_in_workspace", "direct_route", "status_recovery", "permission", "forget"]},
    "routeIntent": {"enum": ["source_detail", "source_library", "ask", "graph", "permissions"]},
    "resolvedPath": {"type": "string", "pattern": "^#/knowledge/"},
    "routeRecoveryResult": {
      "enum": [
        "not_applicable", "restored_direct_open", "restored_after_reload",
        "restored_after_back", "recovered_to_library", "blocked_with_recovery_action"
      ]
    },
    "openOutcome": {"enum": ["focused_existing", "created_new", "direct_open_restored", "recovered", "blocked", "not_applicable"]},
    "observedIds": {"$ref": "v2_external_brain_report.schema.json#/$defs/ObservedIds"},
    "statusObservation": {"$ref": "v2_external_brain_report.schema.json#/$defs/StatusObservation"},
    "errorCode": {"$ref": "v2_external_brain_workspace_contracts.schema.json#/$defs/WorkspaceErrorCode"}
  },
  "allOf": [
    {
      "if": {"properties": {"evidenceClass": {"const": "contract_fixture"}}, "required": ["evidenceClass"]},
      "then": {"properties": {"executionMode": {"const": "contract_fixture"}}}
    },
    {
      "if": {"properties": {"evidenceClass": {"const": "production_acceptance"}}, "required": ["evidenceClass"]},
      "then": {
        "properties": {
          "executionMode": {"enum": ["headless_real_chrome", "visible_real_chrome"]},
          "imagePath": {"not": {"pattern": "^virtual/"}}
        }
      }
    },
    {
      "if": {"properties": {"routeRecoveryResult": {"enum": ["recovered_to_library", "blocked_with_recovery_action"]}}, "required": ["routeRecoveryResult"]},
      "then": {"required": ["errorCode"]}
    },
    {
      "if": {"properties": {"captureMode": {"const": "composite_review_only"}}, "required": ["captureMode"]},
      "then": {"properties": {"captureSurface": {"const": "composite_review"}}}
    },
    {
      "if": {"properties": {"captureMode": {"const": "product_surface"}}, "required": ["captureMode"]},
      "then": {"properties": {"captureSurface": {"not": {"const": "composite_review"}}}}
    },
    {
      "if": {"properties": {"captureSurface": {"const": "host_page"}}, "required": ["captureSurface"]},
      "then": {"properties": {"containerEvidence": {"properties": {"hostPageVisible": {"const": true}, "sidePanelVisible": {"const": false}, "workspaceVisible": {"const": false}}}}}
    },
    {
      "if": {"properties": {"captureSurface": {"const": "side_panel"}}, "required": ["captureSurface"]},
      "then": {"properties": {"containerEvidence": {"properties": {"sidePanelVisible": {"const": true}, "workspaceVisible": {"const": false}}}}}
    },
    {
      "if": {"properties": {"captureSurface": {"enum": ["workspace_page", "route_error"]}}, "required": ["captureSurface"]},
      "then": {"properties": {"containerEvidence": {"properties": {"hostPageVisible": {"const": false}, "sidePanelVisible": {"const": false}, "workspaceVisible": {"const": true}}}}}
    },
    {
      "if": {"properties": {"captureVariantId": {"const": "viewport_sidepanel_360"}}, "required": ["captureVariantId"]},
      "then": {"properties": {"viewport": {"properties": {"width": {"const": 360}}}, "captureMode": {"const": "product_surface"}, "captureSurface": {"const": "side_panel"}}}
    },
    {
      "if": {"properties": {"captureVariantId": {"const": "viewport_sidepanel_420"}}, "required": ["captureVariantId"]},
      "then": {"properties": {"viewport": {"properties": {"width": {"const": 420}}}, "captureMode": {"const": "product_surface"}, "captureSurface": {"const": "side_panel"}}}
    },
    {
      "if": {"properties": {"captureVariantId": {"const": "viewport_workspace_768"}}, "required": ["captureVariantId"]},
      "then": {"properties": {"viewport": {"properties": {"width": {"const": 768}}}, "captureMode": {"const": "product_surface"}, "captureSurface": {"const": "workspace_page"}}}
    },
    {
      "if": {"properties": {"captureVariantId": {"const": "viewport_workspace_1280"}}, "required": ["captureVariantId"]},
      "then": {"properties": {"viewport": {"properties": {"width": {"const": 1280}}}, "captureMode": {"const": "product_surface"}, "captureSurface": {"const": "workspace_page"}}}
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_execution_observation.schema.json",
  "title": "V2-PX Execution Observation",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion", "scenarioId", "capturedAt", "evidenceClass", "entryContext", "attempts",
    "routeEvents", "containerObservations", "runtimeObservation", "ingestCounters"
  ],
  "properties": {
    "schemaVersion": {"const": "v2-external-brain-execution-observation/v6"},
    "scenarioId": {"type": "string", "minLength": 1},
    "capturedAt": {"type": "string", "format": "date-time"},
    "evidenceClass": {"enum": ["contract_fixture", "production_acceptance"]},
    "entryContext": {"$ref": "#/$defs/EntryContext"},
    "attempts": {
      "type": "array",
      "minItems": 1,
      "items": {"$ref": "#/$defs/Attempt"}
    },
    "routeEvents": {
      "type": "array",
      "minItems": 1,
      "items": {"$ref": "#/$defs/RouteEvent"}
    },
    "containerObservations": {
      "type": "array",
      "minItems": 1,
      "items": {"$ref": "#/$defs/ContainerObservation"}
    },
    "runtimeObservation": {"$ref": "#/$defs/RuntimeObservation"},
    "ingestCounters": {
      "type": "object",
      "additionalProperties": false,
      "required": ["before", "after"],
      "properties": {
        "before": {"type": "integer", "minimum": 0},
        "after": {"type": "integer", "minimum": 0}
      }
    },
    "forgetLifecycle": {"$ref": "#/$defs/ForgetLifecycleObservation"}
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "attempts": {
            "contains": {
              "properties": {
                "entryAction": {
                  "properties": {"origin": {"const": "open_in_workspace"}},
                  "required": ["origin"]
                }
              },
              "required": ["entryAction"]
            }
          }
        },
        "required": ["attempts"]
      },
      "then": {
        "properties": {
          "entryContext": {
            "properties": {"status": {"enum": ["observed_valid", "observed_invalid"]}},
            "required": ["status"]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "attempts": {
            "contains": {
              "properties": {"entryAction": {"properties": {"eventType": {"const": "forget"}}, "required": ["eventType"]}},
              "required": ["entryAction"]
            }
          }
        },
        "required": ["attempts"]
      },
      "then": {"required": ["forgetLifecycle"]}
    }
  ],
  "$defs": {
    "RouteIntent": {"enum": ["source_detail", "source_library", "ask", "graph", "permissions"]},
    "ArtifactRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "sha256"],
      "properties": {
        "path": {"type": "string", "minLength": 1},
        "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}
      }
    },
    "EntryContext": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status"],
      "properties": {
        "status": {"enum": ["observed_valid", "observed_invalid", "not_applicable"]},
        "priorRouteIntent": {"$ref": "#/$defs/RouteIntent"},
        "priorResolvedPath": {"type": "string", "pattern": "^#/knowledge/"},
        "priorSourceId": {"type": "string", "minLength": 1},
        "attemptedPath": {"type": "string", "minLength": 1},
        "fallbackReason": {"enum": ["INVALID_ROUTE", "WORKSPACE_NOT_FOUND", "SOURCE_NOT_FOUND", "FORBIDDEN"]}
      },
      "allOf": [
        {
          "if": {"properties": {"status": {"const": "observed_valid"}}, "required": ["status"]},
          "then": {
            "required": ["priorRouteIntent", "priorResolvedPath"],
            "not": {
              "anyOf": [
                {"required": ["attemptedPath"]},
                {"required": ["fallbackReason"]}
              ]
            }
          }
        },
        {
          "if": {"properties": {"status": {"const": "observed_invalid"}}, "required": ["status"]},
          "then": {
            "required": ["attemptedPath", "fallbackReason"],
            "not": {
              "anyOf": [
                {"required": ["priorRouteIntent"]},
                {"required": ["priorResolvedPath"]},
                {"required": ["priorSourceId"]}
              ]
            }
          }
        },
        {
          "if": {"properties": {"status": {"const": "not_applicable"}}, "required": ["status"]},
          "then": {
            "not": {
              "anyOf": [
                {"required": ["priorRouteIntent"]},
                {"required": ["priorResolvedPath"]},
                {"required": ["priorSourceId"]},
                {"required": ["attemptedPath"]},
                {"required": ["fallbackReason"]}
              ]
            }
          }
        },
        {
          "if": {"properties": {"priorRouteIntent": {"const": "source_detail"}}, "required": ["priorRouteIntent"]},
          "then": {"required": ["priorSourceId"]}
        }
      ]
    },
    "Attempt": {
      "type": "object",
      "additionalProperties": false,
      "required": ["sequence", "entryAction", "backgroundResult"],
      "properties": {
        "sequence": {"type": "integer", "minimum": 1},
        "entryAction": {"$ref": "#/$defs/EntryAction"},
        "backgroundResult": {"$ref": "#/$defs/BackgroundResult"}
      }
    },
    "EntryAction": {
      "type": "object",
      "additionalProperties": false,
      "required": ["eventType", "actor", "trustedUserGesture", "requestId", "origin", "routeIntent", "workspaceId", "observedAt"],
      "properties": {
        "eventType": {"enum": ["view_source", "open_workspace", "open_in_workspace", "direct_route", "status_recovery", "permission", "forget"]},
        "actor": {"enum": ["user", "browser_navigation", "test_fault_fixture"]},
        "trustedUserGesture": {"type": "boolean"},
        "requestId": {"type": "string", "minLength": 1},
        "origin": {"enum": ["view_source", "open_workspace", "open_in_workspace", "direct_route", "status_recovery", "permission", "forget"]},
        "routeIntent": {"$ref": "#/$defs/RouteIntent"},
        "workspaceId": {"type": "string", "minLength": 1},
        "sourceId": {"type": "string", "minLength": 1},
        "operationId": {"type": "string", "minLength": 1},
        "observedAt": {"type": "string", "format": "date-time"}
      },
      "allOf": [
        {"if": {"properties": {"eventType": {"const": "view_source"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "view_source"}}}},
        {"if": {"properties": {"eventType": {"const": "open_workspace"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "open_workspace"}}}},
        {"if": {"properties": {"eventType": {"const": "open_in_workspace"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "open_in_workspace"}}}},
        {"if": {"properties": {"eventType": {"const": "direct_route"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "direct_route"}}}},
        {"if": {"properties": {"eventType": {"const": "status_recovery"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "status_recovery"}}}},
        {"if": {"properties": {"eventType": {"const": "permission"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "permission"}}}},
        {"if": {"properties": {"eventType": {"const": "forget"}}, "required": ["eventType"]}, "then": {"properties": {"origin": {"const": "forget"}}}},
        {
          "if": {"properties": {"eventType": {"enum": ["view_source", "open_workspace", "open_in_workspace"]}}, "required": ["eventType"]},
          "then": {"properties": {"actor": {"const": "user"}, "trustedUserGesture": {"const": true}}}
        },
        {
          "if": {"properties": {"origin": {"const": "open_workspace"}}, "required": ["origin"]},
          "then": {"properties": {"routeIntent": {"const": "source_library"}}, "not": {"required": ["sourceId"]}}
        },
        {
          "if": {"properties": {"origin": {"const": "view_source"}}, "required": ["origin"]},
          "then": {"properties": {"routeIntent": {"const": "source_detail"}}, "required": ["sourceId"]}
        }
      ]
    },
    "BackgroundResult": {
      "type": "object",
      "additionalProperties": false,
      "required": ["outcome", "requestId", "observedAt"],
      "properties": {
        "outcome": {"enum": ["focused_existing", "created_new", "direct_open_restored", "recovered", "blocked", "not_applicable"]},
        "requestId": {"type": "string", "minLength": 1},
        "observedAt": {"type": "string", "format": "date-time"},
        "tabId": {"type": "integer", "minimum": 0},
        "workspaceUrl": {"type": "string", "pattern": "^chrome-extension://[^/]+/workspace\\.html#/knowledge/"},
        "errorCode": {"enum": ["WORKSPACE_NOT_FOUND", "SOURCE_NOT_FOUND", "FORBIDDEN", "INVALID_ROUTE", "RUNTIME_OFFLINE", "OPEN_WORKSPACE_FAILED", "UNSUPPORTED_HOST_STRATEGY"]}
      },
      "allOf": [
        {
          "if": {"properties": {"outcome": {"enum": ["focused_existing", "created_new"]}}, "required": ["outcome"]},
          "then": {"required": ["tabId", "workspaceUrl"], "not": {"required": ["errorCode"]}}
        },
        {
          "if": {"properties": {"outcome": {"enum": ["recovered", "blocked"]}}, "required": ["outcome"]},
          "then": {"required": ["errorCode"]}
        }
      ]
    },
    "RouteEvent": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "resolvedPath", "routeIntent", "workspaceId", "observedAt"],
      "properties": {
        "kind": {"enum": ["initial", "push", "reload_restore", "back_restore", "reopen_restore", "recovery", "direct_open_after_forget", "reload_after_forget", "back_after_forget", "reopen_after_forget"]},
        "resolvedPath": {"type": "string", "pattern": "^#/knowledge/"},
        "routeIntent": {"$ref": "#/$defs/RouteIntent"},
        "workspaceId": {"type": "string", "minLength": 1},
        "sourceId": {"type": "string", "minLength": 1},
        "observedAt": {"type": "string", "format": "date-time"},
        "errorCode": {"enum": ["WORKSPACE_NOT_FOUND", "SOURCE_NOT_FOUND", "FORBIDDEN", "INVALID_ROUTE"]}
      },
      "allOf": [
        {
          "if": {"properties": {"kind": {"enum": ["direct_open_after_forget", "reload_after_forget", "back_after_forget", "reopen_after_forget"]}}, "required": ["kind"]},
          "then": {"required": ["sourceId", "errorCode"], "properties": {"routeIntent": {"const": "source_detail"}, "errorCode": {"const": "SOURCE_NOT_FOUND"}}}
        }
      ]
    },
    "ForgetReopenCheck": {
      "type": "object",
      "additionalProperties": false,
      "required": ["mode", "workspaceId", "sourceId", "outcome", "errorCode", "routeRecoveryResult", "observedAt"],
      "properties": {
        "mode": {"enum": ["direct_open", "reload", "back", "reopen"]},
        "workspaceId": {"type": "string", "minLength": 1},
        "sourceId": {"type": "string", "minLength": 1},
        "outcome": {"const": "recovered"},
        "errorCode": {"const": "SOURCE_NOT_FOUND"},
        "routeRecoveryResult": {"const": "recovered_to_library"},
        "observedAt": {"type": "string", "format": "date-time"}
      }
    },
    "ForgetLifecycleObservation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["workspaceId", "sourceId", "statusBefore", "statusAfter", "reopenChecks"],
      "properties": {
        "workspaceId": {"type": "string", "minLength": 1},
        "sourceId": {"type": "string", "minLength": 1},
        "statusBefore": {"allOf": [{"$ref": "v2_knowledge_status.schema.json"}, {"properties": {"sourceBuildStatus": {"const": "trace_ready"}}}]},
        "statusAfter": {"allOf": [{"$ref": "v2_knowledge_status.schema.json"}, {"properties": {"sourceBuildStatus": {"const": "forgotten"}}}]},
        "reopenChecks": {
          "type": "array",
          "minItems": 4,
          "maxItems": 4,
          "items": {"$ref": "#/$defs/ForgetReopenCheck"},
          "allOf": [
            {"contains": {"properties": {"mode": {"const": "direct_open"}}, "required": ["mode"]}, "minContains": 1, "maxContains": 1},
            {"contains": {"properties": {"mode": {"const": "reload"}}, "required": ["mode"]}, "minContains": 1, "maxContains": 1},
            {"contains": {"properties": {"mode": {"const": "back"}}, "required": ["mode"]}, "minContains": 1, "maxContains": 1},
            {"contains": {"properties": {"mode": {"const": "reopen"}}, "required": ["mode"]}, "minContains": 1, "maxContains": 1}
          ]
        }
      }
    },
    "IdObservation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status"],
      "properties": {
        "status": {"enum": ["observed", "not_applicable", "unavailable"]},
        "workspaceId": {"type": "string", "minLength": 1},
        "sourceId": {"type": "string", "minLength": 1},
        "operationId": {"type": "string", "minLength": 1}
      },
      "allOf": [
        {
          "if": {"properties": {"status": {"const": "observed"}}, "required": ["status"]},
          "then": {"required": ["workspaceId"]}
        },
        {
          "if": {"properties": {"status": {"enum": ["not_applicable", "unavailable"]}}, "required": ["status"]},
          "then": {
            "not": {
              "anyOf": [
                {"required": ["workspaceId"]},
                {"required": ["sourceId"]},
                {"required": ["operationId"]}
              ]
            }
          }
        }
      ]
    },
    "ContainerObservation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["container", "ids", "observedAt"],
      "properties": {
        "container": {"enum": ["side_panel", "background", "workspace_page"]},
        "ids": {"$ref": "#/$defs/IdObservation"},
        "observedAt": {"type": "string", "format": "date-time"}
      }
    },
    "RuntimeObservation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["transportOutcome", "observedAt", "ids", "transportEvidence"],
      "properties": {
        "transportOutcome": {"enum": ["response", "timeout", "connection_refused"]},
        "observedAt": {"type": "string", "format": "date-time"},
        "ids": {"$ref": "#/$defs/IdObservation"},
        "responseFingerprint": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
        "transportErrorCode": {"enum": ["RUNTIME_TIMEOUT", "RUNTIME_CONNECTION_REFUSED"]},
        "transportEvidence": {"$ref": "#/$defs/ArtifactRef"}
      },
      "allOf": [
        {
          "if": {"properties": {"transportOutcome": {"const": "response"}}, "required": ["transportOutcome"]},
          "then": {
            "required": ["responseFingerprint"],
            "properties": {"ids": {"properties": {"status": {"const": "observed"}}}},
            "not": {"required": ["transportErrorCode"]}
          }
        },
        {
          "if": {"properties": {"transportOutcome": {"enum": ["timeout", "connection_refused"]}}, "required": ["transportOutcome"]},
          "then": {
            "required": ["transportErrorCode"],
            "properties": {"ids": {"properties": {"status": {"const": "unavailable"}}}},
            "not": {"required": ["responseFingerprint"]}
          }
        },
        {
          "if": {"properties": {"transportOutcome": {"const": "timeout"}}, "required": ["transportOutcome"]},
          "then": {"properties": {"transportErrorCode": {"const": "RUNTIME_TIMEOUT"}}}
        },
        {
          "if": {"properties": {"transportOutcome": {"const": "connection_refused"}}, "required": ["transportOutcome"]},
          "then": {"properties": {"transportErrorCode": {"const": "RUNTIME_CONNECTION_REFUSED"}}}
        }
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_human_review.schema.json",
  "title": "V2-PX Human Product Review",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "evidenceClass", "status", "gateReviews", "blockingIssues", "signedClaim"],
  "properties": {
    "schemaVersion": {"const": "v2-external-brain-human-review/v3"},
    "evidenceClass": {"enum": ["contract_fixture", "production_acceptance"]},
    "status": {"enum": ["pending", "passed", "failed"]},
    "reviewer": {"type": "string", "minLength": 1},
    "reviewedAt": {"type": "string", "format": "date-time"},
    "gateReviews": {
      "type": "object",
      "additionalProperties": false,
      "required": ["G1_entry", "G2_route", "G3_lifecycle", "G4_architecture", "G5_status", "G6_ux_accessibility", "G7_evidence"],
      "properties": {
        "G1_entry": {"$ref": "#/$defs/ReviewItem"},
        "G2_route": {"$ref": "#/$defs/ReviewItem"},
        "G3_lifecycle": {"$ref": "#/$defs/ReviewItem"},
        "G4_architecture": {"$ref": "#/$defs/ReviewItem"},
        "G5_status": {"$ref": "#/$defs/ReviewItem"},
        "G6_ux_accessibility": {"$ref": "#/$defs/ReviewItem"},
        "G7_evidence": {"$ref": "#/$defs/ReviewItem"}
      }
    },
    "blockingIssues": {"type": "array", "items": {"type": "string", "minLength": 1}},
    "signedClaim": {
      "enum": [
        "V2-PX contract fixture review passed; not product acceptance evidence.",
        "V2-PX External Brain Productization passed dual-container real-Chrome acceptance.",
        "V2-PX External Brain Productization acceptance did not pass."
      ]
    }
  },
  "allOf": [
    {
      "if": {"properties": {"status": {"const": "passed"}}, "required": ["status"]},
      "then": {
        "required": ["reviewer", "reviewedAt"],
        "properties": {
          "blockingIssues": {"maxItems": 0},
          "gateReviews": {"$ref": "#/$defs/PassedGateReviews"}
        }
      }
    },
    {
      "if": {"properties": {"status": {"enum": ["pending", "failed"]}}, "required": ["status"]},
      "then": {"properties": {"signedClaim": {"const": "V2-PX External Brain Productization acceptance did not pass."}}}
    },
    {
      "if": {
        "properties": {"status": {"const": "passed"}, "evidenceClass": {"const": "contract_fixture"}},
        "required": ["status", "evidenceClass"]
      },
      "then": {"properties": {"signedClaim": {"const": "V2-PX contract fixture review passed; not product acceptance evidence."}}}
    },
    {
      "if": {
        "properties": {"status": {"const": "passed"}, "evidenceClass": {"const": "production_acceptance"}},
        "required": ["status", "evidenceClass"]
      },
      "then": {"properties": {"signedClaim": {"const": "V2-PX External Brain Productization passed dual-container real-Chrome acceptance."}}}
    }
  ],
  "$defs": {
    "ReviewItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status", "evidenceArtifacts", "notes"],
      "properties": {
        "status": {"enum": ["pending", "passed", "failed"]},
        "evidenceArtifacts": {"type": "array", "items": {"$ref": "#/$defs/ArtifactRef"}},
        "notes": {"type": "string"}
      }
    },
    "PassedGateReviews": {
      "type": "object",
      "additionalProperties": false,
      "required": ["G1_entry", "G2_route", "G3_lifecycle", "G4_architecture", "G5_status", "G6_ux_accessibility", "G7_evidence"],
      "properties": {
        "G1_entry": {"$ref": "#/$defs/PassedReviewItem"},
        "G2_route": {"$ref": "#/$defs/PassedReviewItem"},
        "G3_lifecycle": {"$ref": "#/$defs/PassedReviewItem"},
        "G4_architecture": {"$ref": "#/$defs/PassedReviewItem"},
        "G5_status": {"$ref": "#/$defs/PassedReviewItem"},
        "G6_ux_accessibility": {"$ref": "#/$defs/PassedReviewItem"},
        "G7_evidence": {"$ref": "#/$defs/PassedReviewItem"}
      }
    },
    "PassedReviewItem": {
      "allOf": [
        {"$ref": "#/$defs/ReviewItem"},
        {"properties": {"status": {"const": "passed"}, "evidenceArtifacts": {"minItems": 1}}}
      ]
    },
    "ArtifactRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "sha256"],
      "properties": {
        "path": {"type": "string", "minLength": 1},
        "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_architecture_scan_manifest.schema.json",
  "title": "V2-PX Architecture Scan Manifest",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "evidenceClass", "repositoryCommit", "hashAlgorithm", "pathSeparator", "textEncoding", "pathOrdering", "treeEntryFormat", "pathIndexEntryFormat", "symlinkPolicy", "lineEndingPolicy", "scanRoots", "trackedPaths", "excludedPaths", "canonicalPathIndex", "canonicalSourceTree", "rulesetArtifact", "allowlistArtifact"],
  "properties": {
    "schemaVersion": {"const": "v2-external-brain-architecture-scan-manifest/v2"},
    "evidenceClass": {"enum": ["contract_fixture", "production_acceptance"]},
    "repositoryCommit": {"type": "string", "pattern": "^[a-f0-9]{40}([a-f0-9]{24})?$"},
    "hashAlgorithm": {"const": "sha256"},
    "pathSeparator": {"const": "/"},
    "textEncoding": {"const": "utf-8"},
    "pathOrdering": {"const": "unicode_codepoint_ascending"},
    "treeEntryFormat": {"const": "<mode> <blobSha256> <path>\\n"},
    "pathIndexEntryFormat": {"const": "<path>\\n"},
    "symlinkPolicy": {"const": "hash_link_target_utf8"},
    "lineEndingPolicy": {"const": "raw_bytes"},
    "scanRoots": {
      "type": "array", "minItems": 3, "maxItems": 3, "uniqueItems": true,
      "items": {"enum": ["apps/chrome-extension/entrypoints/sidepanel", "apps/chrome-extension/entrypoints/workspace", "apps/chrome-extension/src/modules/knowledge_workspace"]}
    },
    "trackedPaths": {
      "type": "array", "minItems": 3,
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["path", "blobSha256", "mode"],
        "properties": {
          "path": {"type": "string", "pattern": "^(apps/chrome-extension/entrypoints/(sidepanel|workspace)|apps/chrome-extension/src/modules/knowledge_workspace)/"},
          "blobSha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
          "mode": {"enum": ["100644", "100755", "120000"]},
          "inlineSource": {"$ref": "#/$defs/InlineBytes"}
        }
      }
    },
    "excludedPaths": {"type": "array", "minItems": 3, "maxItems": 3, "uniqueItems": true, "items": {"enum": ["node_modules", "dist", ".output"]}},
    "canonicalPathIndex": {"$ref": "#/$defs/InlineBytes"},
    "canonicalSourceTree": {"$ref": "#/$defs/InlineBytes"},
    "rulesetArtifact": {"$ref": "#/$defs/ArtifactRef"},
    "allowlistArtifact": {"$ref": "#/$defs/ArtifactRef"}
  },
  "allOf": [
    {
      "if": {"properties": {"evidenceClass": {"const": "contract_fixture"}}, "required": ["evidenceClass"]},
      "then": {"properties": {"trackedPaths": {"items": {"required": ["inlineSource"]}}}}
    },
    {
      "if": {"properties": {"evidenceClass": {"const": "production_acceptance"}}, "required": ["evidenceClass"]},
      "then": {"properties": {"trackedPaths": {"items": {"not": {"required": ["inlineSource"]}}}}}
    }
  ],
  "$defs": {
    "InlineBytes": {
      "type": "object", "additionalProperties": false,
      "required": ["encoding", "content", "sha256"],
      "properties": {"encoding": {"const": "utf8"}, "content": {"type": "string", "minLength": 1}, "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}}
    },
    "ArtifactRef": {
      "type": "object", "additionalProperties": false,
      "required": ["path", "sha256"],
      "properties": {"path": {"type": "string", "minLength": 1}, "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}}
    }
  }
}
